#include <sqlite3.h>

using SqliteDb = std::unique_ptr<sqlite3, decltype(&sqlite3_close)>;
using SqliteStmt = std::unique_ptr<sqlite3_stmt, decltype(&sqlite3_finalize)>;

SqliteDb openDatabase(const std::string& path) {
    sqlite3* raw = nullptr;
    int rc = sqlite3_open(path.c_str(), &raw);
    if (rc != SQLITE_OK) {
        if (raw != nullptr) {
            std::cerr << "Failed to open database: " << sqlite3_errmsg(raw) << '\n';
            sqlite3_close(raw);
        } else {
            std::cerr << "Failed to allocate database handle.\n";
        }
        return SqliteDb(nullptr, sqlite3_close);
    }
    return SqliteDb(raw, sqlite3_close);
}

bool fetchUserInformation(sqlite3* db, const std::string& username) {
    sqlite3_stmt* rawStmt = nullptr;
